    <!-- Error Message -->
    <div class="error-message">
      <h1>Sorry, we can't find that.</h1>
    </div>
    <p class="error-suggestion">Perhaps we can help you find the content you're looking for:</p>

    <!-- Search -->
    <form class="search-container" role="search" aria-label="Search IdeaForum" onsubmit="handleSearch(event)">
      <label for="search-field" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Search IdeaForum</label>
